/// <reference path="../../index.d.ts" />
import type { PublicLitElement as LitElement } from "@arcgis/lumina";
import type { AutocompleteItem } from "../calcite-autocomplete-item/customElement.js";

declare module "@arcgis/lumina" {
export interface DeclareCssProperties {
  /** Specifies the component's background color. */
  "--calcite-autocomplete-background-color": "*";
  /** Specifies the component's border color. */
  "--calcite-autocomplete-border-color": "*";
  /** Specifies the component's text color. */
  "--calcite-autocomplete-text-color": "*";
}
}

/** @slot  - A slot for adding `calcite-autocomplete-item`s. */
export abstract class AutocompleteItemGroup extends LitElement {
  /**
   * Specifies the component's heading text.
   *
   * @required
   */
  accessor heading: string;
  /**
   * Specifies the `calcite-autocomplete-item`s in the group.
   *
   * @internal
   */
  get items(): AutocompleteItem[];
  /** Specifies an accessible label for the component. */
  accessor label: any;
  /**
   * Specifies the position of the group in the autocomplete menu.
   *
   * @default 0
   * @internal
   */
  accessor position: number;
}